let actionsExecuted = 0;
// Tools that constitute real work (vs narration: comments/status reads).
const SUBSTANTIVE_TOOLS = new Set([
    "paperclip_create_issue",
    "paperclip_create_agent",
    "paperclip_assign_issue",
    "write_file",
    "run_command",
]);
let substantiveActionDone = false;
const guardedInvoke = async (toolName, args) => {
    // Plan-then-done guard: refuse to close an issue as done when this
    // run produced nothing but comments — that is exactly the "wrote a
    // plan, marked it done, did no work" failure.
    if (toolName === "paperclip_update_issue_status" &&
        args?.status === "done" &&
        !substantiveActionDone) {
        return {
            ok: false,
            error: "Refused: you are marking this issue done but this run performed no substantive action (no sub-task created, no agent created, no file written, no command run). Either do the actual work first, or use status in_review (awaiting someone) / blocked (named blocker) instead. Plans and comments alone do not complete an issue.",
        };
    }
    const result = await toolInvoke(toolName, args);
    if (SUBSTANTIVE_TOOLS.has(toolName) && result && result.ok !== false) {
        substantiveActionDone = true;
    }
    return result;
};
